// AC-6: a wrench on a bike that is already disabled is recorded but changes no counts.
import { expect, test } from "bun:test";
import {
  countRows,
  isDisabledInTable,
  openDatabase,
  recordWrench,
  stationCounts,
  stationOf,
} from "./helpers";

const db = openDatabase();

test("AC-6 (a): a seed-disabled bike: 201, +1 wrench row, station counts change by 0", () => {
  const BIKE = "B-1021"; // has a J-OPEN-* seed job, so is_disabled = 1 from the start
  expect(isDisabledInTable(db, BIKE)).toBe(1);
  const station = stationOf(db, BIKE);
  const before = stationCounts(db, station);
  const wrenchesBefore = countRows(db, "wrenches", BIKE);

  expect(recordWrench(db, { bike_id: BIKE, fault: "SEAT" }).status).toBe(201);

  expect(countRows(db, "wrenches", BIKE) - wrenchesBefore).toBe(1);
  expect(isDisabledInTable(db, BIKE)).toBe(1);
  expect(stationCounts(db, station)).toEqual(before);
});

test("AC-6 (b): wrench a fresh bike twice; the second wrench is 201 and changes no counts", () => {
  const BIKE = "B-1007";
  const station = stationOf(db, BIKE);

  expect(recordWrench(db, { bike_id: BIKE, fault: "BRAKE" }).status).toBe(201);
  const afterFirst = stationCounts(db, station);
  const wrenchesAfterFirst = countRows(db, "wrenches", BIKE);

  // Straight after the first, so both usually land in the same millisecond.
  expect(recordWrench(db, { bike_id: BIKE, fault: "BRAKE" }).status).toBe(201);

  expect(countRows(db, "wrenches", BIKE) - wrenchesAfterFirst).toBe(1);
  expect(isDisabledInTable(db, BIKE)).toBe(1);
  expect(stationCounts(db, station)).toEqual(afterFirst);
});

