// AC-7 (guard): a wrench for a bike that doesn't exist is a 404 and changes nothing.
import { expect, test } from "bun:test";
import { openDatabase, recordWrench, stationStatus } from "./helpers";

const db = openDatabase();

function totalRows(table: "wrenches" | "repair_jobs"): number {
  return (db.query(`SELECT COUNT(*) AS n FROM ${table}`).get() as { n: number }).n;
}

test("AC-7: unknown bike_id gives 404, 0 new rows, all station counts the same", () => {
  const stationsBefore = stationStatus(db).data.stations;
  const wrenchesBefore = totalRows("wrenches");
  const jobsBefore = totalRows("repair_jobs");

  expect(recordWrench(db, { bike_id: "B-NOPE", fault: "BRAKE" }).status).toBe(404);

  expect(totalRows("wrenches")).toBe(wrenchesBefore);
  expect(totalRows("repair_jobs")).toBe(jobsBefore);
  expect(stationStatus(db).data.stations).toEqual(stationsBefore);
});

