insertJob(db, { ...base, job_id: "J-AC9-B", source: "inspection", reported_at: reportedEarly, opened_at: iso(T + HOUR) });
insertJob(db, { ...base, job_id: "J-AC9-A", source: "inspection", reported_at: reportedEarly, opened_at: iso(T + 2 * HOUR) });

