// AC-10: the 40 seed jobs from open-jobs.csv follow SLA-4 from launch, and none become overdue.
import { expect, test } from "bun:test";
import { join } from "node:path";
import {
  HOUR,
  type QueueJob,
  crewQueue,
  expectContractDeadlines,
  expectQueueOrder,
  openDatabase,
  readCsv,
} from "./helpers";

const db = openDatabase();
const seed = readCsv(join(import.meta.dir, "..", "..", "data", "open-jobs.csv"));
// The report came first, so reported_hours_ago is the larger number.
const gapHours = new Map(
  seed.map((row) => [row.job_id, Number(row.reported_hours_ago) - Number(row.opened_hours_ago)]),
);
const seedJobs = () =>
  (crewQueue(db, null).jobs as QueueJob[]).filter((job) => job.job_id.startsWith("J-OPEN-"));

test("AC-10: all 40 seed jobs are in the queue, each with a 0.1h to 1.0h gap", () => {
  expect(seed).toHaveLength(40);
  expect(seedJobs()).toHaveLength(40);
  const outOfRange = [...gapHours].filter(([, gap]) => gap < 0.1 - 1e-9 || gap > 1.0 + 1e-9);
  expect(outOfRange).toEqual([]);
});

test("AC-10: seed deadlines come from reported_at", () => {
  expectContractDeadlines(seedJobs());
});

test("AC-10: each deadline is earlier than opened_at + limit by the CSV gap (±1s)", () => {
  const wrong: string[] = [];
  for (const job of seedJobs()) {
    const limit = (job.source === "wrench" ? 48 : 96) * HOUR;
    const movedBy = Date.parse(job.opened_at) + limit - Date.parse(job.deadline);
    const want = (gapHours.get(job.job_id) ?? Number.NaN) * HOUR;
    if (!(Math.abs(movedBy - want) <= 1000)) wrong.push(`${job.job_id}: ${movedBy}ms, want ${want}ms`);
  }
  expect(wrong).toEqual([]);
});

test("AC-10: 0 seed jobs are overdue at launch", () => {
  const now = Date.now();
  const overdue = seedJobs().filter((job) => Date.parse(job.deadline) < now);
  expect(overdue.map((job) => job.job_id)).toEqual([]);
});

test("AC-10: seed jobs sit in the queue in AC-9 order", () => {
  expectQueueOrder(seedJobs());
});

