// AC-12 (guard): both GBFS feeds keep ttl 60, version "3.0", and a last_updated under 60s old.
import { expect, test } from "bun:test";
import { openDatabase, stationStatus, vehicleStatus } from "./helpers";

const db = openDatabase();

const feeds = [
  ["vehicle_status", vehicleStatus],
  ["station_status", stationStatus],
] as const;

for (const [name, feed] of feeds) {
  test(`AC-12: ${name} has ttl 60, version 3.0, and is no more than 60s old`, () => {
    const response = feed(db);
    expect(response.ttl).toBe(60);
    expect(response.version).toBe("3.0");
    const ageMs = Date.now() - Date.parse(response.last_updated);
    expect(Number.isNaN(ageMs)).toBe(false);
    expect(ageMs).toBeGreaterThanOrEqual(0);
    expect(ageMs).toBeLessThanOrEqual(60_000);
  });
}

