// AC-13 (guard): a wrench on one bike changes no other bike's is_disabled in vehicle_status.
import { expect, test } from "bun:test";
import { openDatabase, recordWrench, vehicleStatus } from "./helpers";

const db = openDatabase();
const BIKE = "B-1008";

const snapshot = () =>
  new Map(vehicleStatus(db).data.vehicles.map((v) => [v.vehicle_id, v.is_disabled]));

test("AC-13: exactly 0 other bikes change is_disabled", () => {
  const before = snapshot();
  expect(recordWrench(db, { bike_id: BIKE, fault: "BELL" }).status).toBe(201);
  const after = snapshot();

  expect(after.size).toBe(before.size);
  const changed = [...after]
    .filter(([id, disabled]) => id !== BIKE && before.get(id) !== disabled)
    .map(([id]) => id);
  expect(changed).toEqual([]);
});

